use quince_core::{ring::RingVec,types::Trade};use quince_indicators::{CustomIndicator,CustomIndicatorError,CustomIndicatorRegistration,IndicatorDescriptor,IndicatorInput,IndicatorOutput,IndicatorParameter};static P:&[IndicatorParameter]=&[IndicatorParameter{name:"period",min:1.,max:10000.}];static D:IndicatorDescriptor=IndicatorDescriptor{name:"custom_vwma",input:IndicatorInput::Trade,output:IndicatorOutput::ScalarF64,parameters:P};pub static REGISTRATION:CustomIndicatorRegistration=CustomIndicatorRegistration{descriptor:&D,create};struct I{p:usize,n:RingVec,d:RingVec}fn create(x:&[f64])->Result<Box<dyn CustomIndicator>,CustomIndicatorError>{let p=x[0]as usize;Ok(Box::new(I{p,n:RingVec::new(p),d:RingVec::new(p)}))}impl CustomIndicator for I{fn on_trade(&mut self,t:&Trade)->Option<f64>{self.n.push(t.price*t.qty);self.d.push(t.qty);(self.n.len()==self.p).then(||self.n.iter().sum::<f64>()/self.d.iter().sum::<f64>())}}
#[cfg(test)]mod tests{use super::*;use chrono::Utc;use quince_core::types::Side;fn t(p:f64,q:f64)->Trade{Trade{price:p,qty:q,time:Utc::now(),side:Side::Buy,trade_id:1}}#[test]fn vwma(){let mut i=create(&[2.]).unwrap();i.on_trade(&t(2.,1.));assert_eq!(i.on_trade(&t(4.,3.)),Some(3.5));}}
